"""v4.50 G1-b2 원거리 원형 측정 공용: 실제 체력 몬스터 무리를 자동 전투로 '처치까지' 잡으며 피격률 · 피해를 잰다.
PACK_JS([sp,lv,n,seed,beh]) — 지금 맵에서 종 sp 일반 개체 n마리(레벨 lv · 실제 능력치 · 원거리면 체력 ×hpK)를 집 근처에 두고
플레이어를 무리에서 100 떨어뜨린 뒤 자동 전투로 다 잡을 때까지(최대 120초 · window.__packSec로 바꿈 · v4.52: window.__packHpK로 무리 체력 배율 — 측정 캐릭터가 Lv18 이상에서 4마리를 2~5분 걸려 잡아 회피 · 추격 순환이 측정을 덮던 것). beh='melee'면 같은 무리를 근접형(체력 그대로)으로.
v4.55: 판마다 레벨 · 경험치를 되돌린다(측정 순서 무관).
돌려주는 값: taken(받은 피해) · shots · hits · sec(처치까지 초) · killed · away(v4.53: 회피해 자동 전투 범위 밖으로 간 수 — 판은 거기서 끝)"""
PACK_JS="""([sp,lv,n,seed,beh])=>{const g=__g,S=g.S,P=g.player;let a=seed>>>0;const sr=()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};/* v4.55 G1-b2d: three.js가 새 재질 · 메시를 만들 때 쓰는 UUID 생성(ct)도 Math.random을 쓴다 — 재질 캐시(addOf)가 이미 찼는지(앞 판 · 페이지 이력)에 따라 씨앗 난수를 먹어 같은 씨앗이 갈렸다. UUID 생성 프레임이면 씨앗 밖 난수를 준다 */if(!window.__R0||window.__R0.__pk){let k=0x2545F491;window.__R0=()=>{k^=k<<13;k^=k>>>17;k^=k<<5;return (k>>>0)/4294967296;};}if(window.__u3===undefined&&window.THREE){const R=Math.random;let ln='';Math.random=()=>{const L0=Error.stackTraceLimit;Error.stackTraceLimit=4;ln=(new Error().stack.split('\\n')[2]||'');Error.stackTraceLimit=L0;return .5;};new THREE.Object3D();Math.random=R;window.__u3=ln.trim().split('(')[0];}{const tag=window.__u3,R0=window.__R0;Math.random=tag?()=>{const L0=Error.stackTraceLimit;Error.stackTraceLimit=3;const f=new Error().stack.split('\\n')[2]||'';Error.stackTraceLimit=L0;return f.trim().startsWith(tag)?R0():sr();}:sr;Math.random.__pk=1;}
 const keep=g.MOB_B[sp];if(beh==='melee')delete g.MOB_B[sp];else if(beh==='charge'&&!keep)g.MOB_B[sp]={b:'charge'};const rng=g.mobBeh({sp})==='ranged';
 const L=g.mobs.filter(e=>e.sp===sp&&!e.boss&&!e.eliteOf&&(!window.__packZone||e.zone===window.__packZone)).slice(0,n);/* v4.57: window.__packZone — 한 종이 두 사냥터에 있을 때(잿빛박쥐 e1 · e3) 고른 사냥터 개체로 */if(L.length<n){if(keep)g.MOB_B[sp]=keep;return null;}
 for(const e of g.mobs){e.aggro=false;e.ret=false;e.aim=null;if(!L.includes(e)){e.dead=true;e.deadT=-1e9;e.respawn=1e9;}}
 const c=L[0];let rot=(seed*2.399963)%6.2832;/* 씨앗마다 무리 방향 · 다가오는 방향을 돌린다(지형 · 나무가 한 방향만 막아 결과가 씨앗과 무관해지던 것) */if(!c._h0)c._h0={x:c.home.x,y:c.home.y};const cx=c._h0.x,cy=c._h0.y;/* v4.51: 플레이어 · 집 자리가 막힌 칸(물 · 나무)이면 방향을 돌린다 — v4.50 묶음 B의 꼬리 한 판은 플레이어가 막힌 칸에 놓여 한 걸음도 못 움직인 측정 잘못이었다 */
 if(g.blockedAt){const G=window.__gap||70,no=g.reachOk?(x,y)=>!g.reachOk(x,y):(x,y)=>g.blockedAt(x,y)/* v4.52: 막힌 칸뿐 아니라 마을에서 닿지 않는 칸(용암 · 물 사이 섬)도 피한다 — 에르나 · 수정 호숫가에서 무리가 섬에 놓여 180초 동안 못 잡던 판 */,bad=r=>no(cx+Math.cos(r+1)*100,cy+Math.sin(r+1)*100)||[1,2,3].some(i=>no(cx+Math.cos(r+i*2.1)*G,cy+Math.sin(r+i*2.1)*G));for(let k=0;k<12&&bad(rot);k++)rot+=.5236;}
 /* v4.55 G1-b2d: 판 시작 상태 고정 — ① 게임 시각을 4초 칸(저장 · 보충 틱)의 시작에 맞춘다 ② 마을 장식 NPC(돌아다니며 Math.random을 씀)를 제자리로. 앞 판 · 페이지 시작 프레임 수가 남긴 위상이 씨앗 난수열을 밀어 같은 씨앗이 판마다 달랐다 */
 for(const e of L){e.dead=true;e.deadT=-1e9;e.respawn=1e9;}{const T=4,goal=(Math.floor(g.t/T)+1)*T;while(goal-g.t>.05)g.step(1,.05);if(goal-g.t>0)g.step(1,goal-g.t);}/* 마지막 걸음은 t를 4의 배수에 정확히 맞춘다(Sterbenz: 남은 폭 ≤ 0.05) */for(const e of g.mobs)if(!L.includes(e)){e.aggro=false;e.ret=false;e.aim=null;e.dead=true;e.deadT=-1e9;e.respawn=1e9;}/* 맞추는 동안 4초 틱(ensureFieldBosses)이 되살린 개체를 다시 치운다 */
 if(g.npcList)for(const q of g.npcList)if(q.deco){q.x=q.hx;q.y=q.hy;q.mv=null;q.next=1;q.walk=0;}
 a=seed>>>0; L.forEach((m,i)=>{const an=rot+i*2.1;m.home.x=cx+Math.cos(an)*(window.__gap||70)*(i>0);m.home.y=cy+Math.sin(an)*(window.__gap||70)*(i>0);m.x=m.home.x;m.y=m.home.y;m.dead=false;m.deadT=0;m.respawn=1e9;m.lv=lv;const ms=g.mobStats(lv,false);m.atk=ms.atk;m.def=ms.def;m.max=m.hp=Math.max(1,Math.round(ms.hp*(rng?g.RANGED.hpK:1)*(window.__packHpK||1)));m.atkT=.5+i*.4;m.wind=0;m.aggro=true;m.ret=false;m.aim=null;m.evd=false;m.evU=0;m.evL=0;m.apT=0;m.stk=null;m.chg=null;m.next=1;m.phase=i;m.blockT=0;m.face=-1;m.hit=0;m.moving=false;/* v4.55: 배회 타이머 · 막힘 · 애니메이션 위상도(앞 판이 남김) */m.stag=0;m.chgCd=0;m.backT=0;});/* v4.52: 회피 표시(evd · evU · evL)도 판마다 지운다 — 앞 판의 회피 상태가 다음 판에 남아 같은 씨앗이 혼자 돌릴 때와 달랐다 */
 if(g.wPct()>.4){const eq=Object.values(S.eq);S.items=S.items.filter(i=>eq.includes(i.u)||i.lock);for(const k in S.bag)S.bag[k]=0;S.stone=0;}/* v4.53: 앞 판들의 드롭이 쌓여 무게 82%(tooHeavy)면 공격을 못 해 무리를 못 잡던 것(동굴버섯 Lv19 B · 판 순서에 따라) — 가방을 비운다 */
 g.shots.length=0;g.tele.length=0;g.clearStatus();P.dead=false;P.x=cx+Math.cos(rot+1)*100;P.y=cy+Math.sin(rot+1)*100;P.hp=1e8;P.shield=0;P.mp=9999;P.lastHit=1e12;P.hurt=0;P.dash=0;S.hpPot=0;g.setTarget(null);g.resetAuto&&g.resetAuto();P.cd.fill(0);P.atkT=0;P.spin=0;P.swing=0;P.buffT=0;P.guardT=0;P.fervT=0;P.dead=false;P.face=1;P.dir='down';P.swingTgt=null;P.swingHit=false;P.moving=false;/* v4.55: 바라보는 방향 · 휘두르기 대상도(앞 판이 남김) */
 const lv0=[S.lv,S.xp,S.sp,S.kp];const sv0=JSON.stringify({items:S.items,bag:S.bag,gold:S.gold,stone:S.stone,kills:S.kills,acq:S.acq,nu:S.nu});/* v4.55: 드롭 · 골드 · 처치 수 · 획득 기록도 판마다 되돌린다(20판 뒤 같은 씨앗의 처치 시간이 0.1~0.6초 달랐다) *//* v4.55 G1-b2d: 측정 중 처치 경험치로 캐릭터가 오르던 것(Lv5 → 7 · 20판) — 판마다 레벨 · 경험치 · 포인트를 되돌린다. 앞 판이 남긴 레벨이 다음 판의 처치 속도 · 선공(aggroOn)을 바꿔 측정 순서에 따라 결과가 갈렸다 */
 const n0=g.STAT.shotN||0,h0=g.STAT.shotHit||0,c0=g.STAT.chgN||0,ch0=g.STAT.chgHit||0;g.setAuto(true);let sec=0;
 const SEC=window.__packSec||120;const gone=m=>!m.dead&&!m.aggro&&sec>12&&g.anchor&&Math.hypot(m.x-g.anchor.x,m.y-g.anchor.y)>(window.__packAnc||230)&&Math.hypot(m.x-P.x,m.y-P.y)>180;/* v4.57: window.__packAnc — 자리 거리 기준을 바꿈(기본 230 · 돌진 날짐승 측정은 180: 추격 한계로 집에 돌아간 개체가 자리 189 · 나 199에서 평화 상태로 남아 자동 전투(찾기 170)도 몬스터도 서로 안 움직이던 판) */ /* v4.53: 회피해 집으로 간 원거리가 자동 전투 범위(자리 220 · 찾기 170) 밖에서 평화 상태면 이 싸움에서 빠진 것 — 실제 자동 전투도 쫓지 않는다 */
 const DT=window.__packDt||1/32;/* v4.55: 측정 걸음 1/32초(이진수로 정확) — 0.05초 걸음은 t가 클수록 반올림이 달라 '경직 끝(stag>t)' 같은 같은 시각 비교가 앞 판 수에 따라 뒤집혔다 */while(sec<SEC&&L.some(m=>!m.dead&&!gone(m))){g.step(1,DT);sec+=DT;for(const m of L)if(m.dead)m.respawn=1e9;/* v4.52: 처치 때 killMob이 재출현 시간을 다시 넣어 잡은 개체가 되살아나던 것(처치가 늦은 Lv18+ 무리에서 끝나지 않음) */P.lastHit=1e12;if(P.hp<1e7)P.hp=1e8;}
 S.lv=lv0[0];S.xp=lv0[1];S.sp=lv0[2];S.kp=lv0[3];Object.assign(S,JSON.parse(sv0));const taken=1e8-P.hp,killed=L.filter(m=>m.dead).length,away=L.filter(gone).length;/* v4.52: 처치 수는 정리 전에 센다(전엔 정리 뒤라 늘 n) */g.setAuto(false);for(const m of L){m.respawn=1e9;m.dead=true;m.deadT=-1e9;}g.shots.length=0;g.tele.length=0;if(keep)g.MOB_B[sp]=keep;
 return {taken,shots:(g.STAT.shotN||0)-n0,hits:(g.STAT.shotHit||0)-h0,chg:(g.STAT.chgN||0)-c0,chgHit:(g.STAT.chgHit||0)-ch0,sec,killed,away};}"""
